/** Sorted, de-duplicated list of known bookmaker display names for type-ahead suggestions. */
export const BOOKMAKER_SUGGESTIONS: string[] = Array.from(
    new Set(Object.values(BOOKMAKER_META).map((meta) => meta.name))
).sort((a, b) => a.localeCompare(b));

export function normalizeBookmakerKey(value: unknown) {
    return String(value || '').trim().toLowerCase().replace(/\s+/g, ' ');
}

export function titleCaseBookmaker(value: unknown) {
    const bookmaker = String(value || '').trim();
    if (!bookmaker) return '-';
    return bookmaker
        .split(' ')
        .map((word) => word.charAt(0).toUpperCase() + word.slice(1).toLowerCase())
        .join(' ');
}

export function getBookmakerMeta(value: unknown) {
    const key = normalizeBookmakerKey(value);
    if (BOOKMAKER_META[key]) return BOOKMAKER_META[key];
    // Collapse spaces/punctuation so "bet365"/"skybet" match "bet 365"/"sky bet" catalog keys.
    const collapsed = key.replace(/[\s._-]+/g, '');
    if (collapsed) {
        for (const [metaKey, meta] of Object.entries(BOOKMAKER_META)) {
            if (metaKey.replace(/[\s._-]+/g, '') === collapsed || meta.slug === collapsed) {
                return meta;
            }
        }
    }
    return { name: titleCaseBookmaker(value), slug: key.replace(/[^a-z0-9]+/g, '-') };
}

export function getBookmakerButtonUrl(value: unknown) {
    const meta = getBookmakerMeta(value);
    if (!meta.slug) return '';
    return `https://www.top100bookmakers.com/buttons/${meta.slug}-button.png`;
}
